<?php
declare(strict_types=1);
require_once __DIR__ . '/database.php';

ini_set('display_errors','0');
error_reporting(E_ALL);
date_default_timezone_set('UTC');
$https = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off');
session_name('c8b_sid');
session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>$https,'httponly'=>true,'samesite'=>'Lax']);
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
header('X-Content-Type-Options: nosniff');
header('X-Frame-Options: DENY');
header('Referrer-Policy: no-referrer');

try {
    $pdo = c8b_database();
    c8b_schema_if_needed($pdo);
} catch (Throwable $e) {
    error_log('C8B database bootstrap failed: ' . $e->getMessage());
    http_response_code(500);
    header('Cache-Control: no-store');
    $requestPath = parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH) ?: '/';
    $isApiRequest = str_starts_with($requestPath, '/api/');
    $message = 'The local file database is not ready. Please check SQLite support and folder permissions.';
    $detail = strtolower($e->getMessage());
    if (str_contains($detail, 'could not find driver')) {
        $message = 'PHP is missing the PDO SQLite driver (pdo_sqlite). Enable it for the PHP version serving this website.';
    } elseif (str_contains($detail, 'could not create the database folder') || str_contains($detail, 'not writable')) {
        $message = 'PHP cannot write to the database folder. Enable pdo_sqlite and give PHP write permission to the database folder, or set C8B_DB_PATH to a writable private path.';
    } elseif ($e instanceof PDOException) {
        $message = 'Could not open the SQLite database file. Enable pdo_sqlite and verify that its folder is writable by PHP.';
    }
    if ($isApiRequest) {
        header('Content-Type: application/json; charset=utf-8');
        echo json_encode(['error' => $message], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    } else {
        header('Content-Type: text/html; charset=utf-8');
        $safeMessage = htmlspecialchars($message, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>C8B setup required</title><style>body{margin:0;background:#0b0d16;color:#f4f5fb;font:16px/1.6 system-ui,sans-serif;display:grid;min-height:100vh;place-items:center}.panel{max-width:680px;margin:24px;padding:32px;border:1px solid #303348;border-radius:18px;background:#141725}h1{margin-top:0}p{color:#c2c6d7}code{color:#c8b8ff}</style></head><body><main class="panel"><h1>C8B needs a database setup</h1><p>' . $safeMessage . '</p><p>For local development, make sure the active PHP runtime has <code>pdo_sqlite</code> enabled. On shared hosting, create a MySQL database in the hosting panel and put its exact credentials in <code>php/database.config.php</code>.</p></main></body></html>';
    }
    exit;
}

function c8b_schema_if_needed(PDO $pdo): void {
 static $done = false;
 if ($done) return;
 $done = true;

 // Create or repair the local SQLite file database without requiring a MySQL server.
 $requiredTables = ['users', 'categories', 'projects', 'project_files', 'downloads', 'oauth_accounts', 'site_settings', 'contact_messages'];
 $placeholders = implode(',', array_fill(0, count($requiredTables), '?'));
 $check = $pdo->prepare("SELECT name FROM sqlite_master WHERE type='table' AND name IN (" . $placeholders . ")");
 $check->execute($requiredTables);
 $existingTables = array_column($check->fetchAll(PDO::FETCH_ASSOC), 'name');
 if (count(array_diff($requiredTables, $existingTables)) > 0) {
  $file = dirname(__DIR__) . '/database/schema.sqlite.sql';
  $sql = @file_get_contents($file);
  if ($sql === false) throw new RuntimeException('SQLite schema file missing.');
  $sql = preg_replace('/^\\s*--.*$/m', '', $sql) ?? $sql;
  foreach (preg_split('/;\\s*(?:\\r?\\n|$)/', $sql) ?: [] as $statement) {
   $statement = trim($statement);
   if ($statement !== '') $pdo->exec($statement);
  }
 }
 // Bootstrap the requested Owner account on a fresh install, or when no Owner exists.
 if ((int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='owner'")->fetchColumn() === 0) {
  $hash = '$2y$12$xHs2tVfhEDmQ16rlnSwZve8SVi5mu2mP2HFWLFJF/OChpu5tYCyRm';
  $existing = $pdo->prepare('SELECT id FROM users WHERE username = ? LIMIT 1');
  $existing->execute(['admin']);
  $adminId = $existing->fetchColumn();
  if ($adminId) {
   $update = $pdo->prepare("UPDATE users SET email=?, password_hash=?, role='owner', is_active=1 WHERE id=?");
   $update->execute(['admin@c8b.local', $hash, $adminId]);
  } else {
   $insert = $pdo->prepare("INSERT INTO users(username,email,password_hash,role,is_active) VALUES(?,?,?,?,1)");
   $insert->execute(['admin', 'admin@c8b.local', $hash, 'owner']);
  }
 }
}
function db(): PDO {global $pdo;return $pdo;}
function h($v): string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function api(array $data,int $status=200): never {http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function req_method(): string{return strtoupper($_SERVER['REQUEST_METHOD']??'GET');}
function req_path(): string{$p=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';return rawurldecode($p);}
function body(): array{$type=strtolower($_SERVER['CONTENT_TYPE']??'');if(str_contains($type,'application/json')){$v=json_decode(file_get_contents('php://input')?:'{}',true);return is_array($v)?$v:[];}return is_array($_POST)?$_POST:[];}
function go(string $url,int $status=302): never{header('Location: '.$url,true,$status);exit;}
function q(string $sql,array $params=[]): PDOStatement{$s=db()->prepare($sql);$s->execute($params);return $s;}
function row(string $sql,array $params=[]): ?array{$v=q($sql,$params)->fetch();return $v?:null;}
function rows(string $sql,array $params=[]): array{return q($sql,$params)->fetchAll();}
function nrows(string $sql,array $params=[]): int{return (int)(row($sql,$params)['n']??0);}
function txt($v,int $max=5000): string{if(!is_string($v)&&!is_numeric($v))return '';return function_exists('mb_substr')?mb_substr(trim((string)$v),0,$max,'UTF-8'):substr(trim((string)$v),0,$max);}
function uid($v): ?int{if(!is_scalar($v)||!preg_match('/^[1-9][0-9]*$/',(string)$v))return null;$i=filter_var($v,FILTER_VALIDATE_INT);return $i!==false&&$i>0?$i:null;}
function arr($v): array{$x=is_array($v)?$v:json_decode((string)($v??'[]'),true);return is_array($x)?$x:[];}
function j($v): string{return json_encode($v,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?:'[]';}
function user_now(): ?array{if(empty($_SESSION['user_id']))return null;$u=row('SELECT id,username,email,role,is_active,created_at,updated_at FROM users WHERE id=? LIMIT 1',[(int)$_SESSION['user_id']]);if(!$u||!(int)$u['is_active']){unset($_SESSION['user_id']);return null;}return $u;}
function require_user(bool $json=false): array{$u=user_now();if(!$u){if($json)api(['error'=>'Authentication required.'],401);go('/login');}return $u;}
function require_owner(): array{$u=require_user(true);if($u['role']!=='owner')api(['error'=>'You do not have permission to access this resource.'],403);return $u;}
function csrf(): string{if(empty($_SESSION['csrfToken']))$_SESSION['csrfToken']=bin2hex(random_bytes(32));return (string)$_SESSION['csrfToken'];}
function check_csrf(): void{$b=body();$got=(string)($_SERVER['HTTP_X_CSRF_TOKEN']??($b['csrfToken']??''));$want=(string)($_SESSION['csrfToken']??'');if($got===''||$want===''||!hash_equals($want,$got))api(['error'=>'Request verification failed. Refresh the page and try again.'],403);}
function limit_hit(string $key,int $max,int $seconds): bool{$now=time();$_SESSION['_limits']??=[];$b=$_SESSION['_limits'][$key]??['t'=>$now,'n'=>0];if($now-(int)$b['t']>=$seconds)$b=['t'=>$now,'n'=>0];$b['n']++;$_SESSION['_limits'][$key]=$b;return $b['n']>$max;}
function safe_user(array $u): array{return ['id'=>(int)$u['id'],'username'=>$u['username'],'email'=>$u['email'],'role'=>$u['role'],'createdAt'=>$u['created_at']];}
function slug(string $s): string{return substr(trim(preg_replace('/[^a-z0-9]+/','-',strtolower(trim($s)))??'','-'),0,80);}
function unique_slug(string $title,?int $except=null): string{$base=slug($title)?:'project';$s=$base;$i=2;while(row('SELECT id FROM projects WHERE slug=? AND id<>? LIMIT 1',[$s,$except??0]))$s=substr($base,0,70).'-'.$i++;return $s;}
function iso($v): string{if(!$v)return '';try{return (new DateTimeImmutable((string)$v,new DateTimeZone('UTC')))->format('Y-m-d\TH:i:s.v\Z');}catch(Throwable $e){return (string)$v;}}
function base_projects(): string{return "SELECT p.*,c.name category_name,c.slug category_slug,(SELECT COUNT(*) FROM project_files f WHERE f.project_id=p.id AND f.status='active') file_count,(SELECT COUNT(*) FROM downloads d JOIN project_files f ON f.id=d.project_file_id WHERE f.project_id=p.id AND f.status='active') download_count FROM projects p LEFT JOIN categories c ON c.id=p.category_id";}
function get_project(int $id): ?array{return row(base_projects().' WHERE p.id=?',[$id]);}
function psummary(array $p): array{return ['id'=>(int)$p['id'],'title'=>$p['title'],'name'=>$p['title'],'slug'=>$p['slug'],'description'=>$p['description'],'categoryId'=>$p['category_id']===null?null:(int)$p['category_id'],'categoryName'=>$p['category_name']??null,'version'=>$p['version'],'status'=>$p['status'],'featured'=>(bool)$p['featured'],'icon'=>$p['icon_path'],'banner'=>$p['banner_path'],'screenshots'=>arr($p['screenshots_json']??'[]'),'features'=>arr($p['features_json']??'[]'),'requirements'=>$p['requirements']??'','changelog'=>$p['changelog']??'','externalLinks'=>arr($p['external_links_json']??'[]'),'createdAt'=>iso($p['created_at']??''),'updatedAt'=>iso($p['updated_at']??''),'downloads'=>(int)($p['download_count']??0),'files'=>(int)($p['file_count']??0)];}
function get_file(int $id): ?array{return row('SELECT f.*,p.title project_title,(SELECT COUNT(*) FROM downloads d WHERE d.project_file_id=f.id) download_count FROM project_files f JOIN projects p ON p.id=f.project_id WHERE f.id=?',[$id]);}
function fsummary(array $f): array{return ['id'=>(int)$f['id'],'projectId'=>(int)$f['project_id'],'projectTitle'=>$f['project_title']??null,'filename'=>$f['original_name'],'version'=>$f['version'],'size'=>(int)$f['size_bytes'],'uploadDate'=>iso($f['created_at']),'downloads'=>(int)($f['download_count']??0),'status'=>$f['status']];}
function murl($f): string{return is_string($f)&&preg_match('/^[a-f0-9-]{36}\.(png|jpe?g|webp|gif)$/i',$f)?'/media/'.rawurlencode($f):'';}
function rootdir(): string{return dirname(__DIR__);}
function remove_file(string $root,$name): void{if(is_string($name)&&preg_match('/^[a-f0-9-]{36}\.[a-z0-9]{1,10}$/i',$name)&&is_file($root.'/'.$name))@unlink($root.'/'.$name);}
function upload(string $field,string $dest,array $exts,int $max): array{
 if(empty($_FILES[$field])||!is_array($_FILES[$field]))throw new RuntimeException('Choose a file to upload.');
 $f=$_FILES[$field];if(($f['error']??4)!==UPLOAD_ERR_OK)throw new RuntimeException(($f['error']??0)===UPLOAD_ERR_INI_SIZE?'The hosting upload limit was exceeded.':'Upload failed. Check the file size and try again.');
 $name=basename(str_replace('\\','/',(string)$f['name']));$name=preg_replace('/[\x00-\x1F\x7F]/','',$name)??'';$name=substr(trim($name)?:'download',0,180);$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));
 if(!in_array($ext,$exts,true))throw new RuntimeException('Unsupported file type.');if((int)$f['size']>$max)throw new RuntimeException('The file exceeds the configured upload limit.');
 $uuid=sprintf('%s-%s-4%s-%x-%s',bin2hex(random_bytes(4)),bin2hex(random_bytes(2)),substr(bin2hex(random_bytes(2)),1),random_int(0x8000,0xbfff),bin2hex(random_bytes(6)));$stored=$uuid.'.'.$ext;
 if(!is_dir($dest)&&!mkdir($dest,0755,true)&&!is_dir($dest))throw new RuntimeException('Storage directory unavailable.');
 if(!move_uploaded_file((string)$f['tmp_name'],$dest.'/'.$stored))throw new RuntimeException('Could not store uploaded file.');
 $mime=function_exists('finfo_open')?(new finfo(FILEINFO_MIME_TYPE))->file($dest.'/'.$stored):'application/octet-stream';
 return ['original'=>$name,'stored'=>$stored,'size'=>(int)$f['size'],'mime'=>$mime?:'application/octet-stream'];
}

function oauth_http(string $url,?string $post=null,array $headers=[]): array {
 if(!function_exists('curl_init'))throw new RuntimeException('The hosting PHP cURL extension is required for OAuth sign-in.');
 $ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>20,CURLOPT_HTTPHEADER=>$headers]);
 if($post!==null){curl_setopt($ch,CURLOPT_POST,true);curl_setopt($ch,CURLOPT_POSTFIELDS,$post);}
 $raw=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$error=curl_error($ch);curl_close($ch);
 if($raw===false||$status<200||$status>=300)throw new RuntimeException('OAuth provider request failed: '.$status.' '.$error);
 $json=json_decode((string)$raw,true);if(!is_array($json))throw new RuntimeException('OAuth provider returned invalid data.');return $json;
}
function oauth_callback_url(string $provider): string {
 $key=strtoupper($provider).'_CALLBACK_URL';$configured=getenv($key);
 if($configured)return $configured;
 $scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';
 $host=(string)($_SERVER['HTTP_HOST']??'localhost');
 if(!preg_match('/^[A-Za-z0-9.-]+(?::[0-9]{1,5})?$/',$host))throw new RuntimeException('Configure the OAuth callback URL explicitly.');
 return $scheme.'://'.$host.'/auth/'.$provider.'/callback';
}
function oauth_start(string $provider): never {
 $id=getenv(strtoupper($provider).'_CLIENT_ID');$secret=getenv(strtoupper($provider).'_CLIENT_SECRET');
 if(!$id||!$secret)go('/login?error=oauth_unavailable');
 $state=bin2hex(random_bytes(32));$_SESSION['oauth_state_'.$provider]=$state;
 if($provider==='google')$base='https://accounts.google.com/o/oauth2/v2/auth';
 else $base='https://discord.com/oauth2/authorize';
 $scope=$provider==='google'?'openid email profile':'identify email';
 $url=$base.'?'.http_build_query(['client_id'=>$id,'redirect_uri'=>oauth_callback_url($provider),'response_type'=>'code','scope'=>$scope,'state'=>$state]);
 go($url,302);
}
function oauth_callback(string $provider): never {
 try {
  $expected=(string)($_SESSION['oauth_state_'.$provider]??'');unset($_SESSION['oauth_state_'.$provider]);
  if(!$expected||!isset($_GET['state'])||!is_string($_GET['state'])||!hash_equals($expected,$_GET['state'])||empty($_GET['code'])||!is_string($_GET['code']))throw new RuntimeException('OAuth state or authorization code was invalid.');
  $id=getenv(strtoupper($provider).'_CLIENT_ID');$secret=getenv(strtoupper($provider).'_CLIENT_SECRET');if(!$id||!$secret)throw new RuntimeException('OAuth provider is not configured.');
  $tokenUrl=$provider==='google'?'https://oauth2.googleapis.com/token':'https://discord.com/api/oauth2/token';
  $token=oauth_http($tokenUrl,http_build_query(['client_id'=>$id,'client_secret'=>$secret,'code'=>$_GET['code'],'grant_type'=>'authorization_code','redirect_uri'=>oauth_callback_url($provider)]),['Content-Type: application/x-www-form-urlencoded','Accept: application/json']);
  if(empty($token['access_token']))throw new RuntimeException('OAuth provider did not return an access token.');
  if($provider==='google'){$profile=oauth_http('https://openidconnect.googleapis.com/v1/userinfo',null,['Authorization: Bearer '.$token['access_token'],'Accept: application/json']);$email=(string)($profile['email']??'');$verified=($profile['email_verified']??false)===true;$display=(string)($profile['name']??$profile['given_name']??'user');$providerId=(string)($profile['sub']??'');}
  else{$profile=oauth_http('https://discord.com/api/users/@me',null,['Authorization: Bearer '.$token['access_token'],'Accept: application/json']);$email=(string)($profile['email']??'');$verified=($profile['verified']??false)===true;$display=(string)($profile['global_name']??$profile['username']??'user');$providerId=(string)($profile['id']??'');}
  $email=strtolower(trim($email));if(!$verified||!filter_var($email,FILTER_VALIDATE_EMAIL)||$providerId==='')throw new RuntimeException('A verified email address is required for OAuth login.');
  $linked=row('SELECT user_id FROM oauth_accounts WHERE provider=? AND provider_user_id=?',[$provider,$providerId]);
  if($linked){$account=row('SELECT * FROM users WHERE id=? AND is_active=1',[(int)$linked['user_id']]);if(!$account)throw new RuntimeException('This account is unavailable.');}
  else{
   if(row('SELECT id FROM users WHERE email=? LIMIT 1',[$email]))throw new RuntimeException('An account with this email already exists. Sign in with your password first; automatic account linking is disabled.');
   $base=preg_replace('/[^a-z0-9_]/','_',strtolower($display))??'user';$base=trim(substr($base,0,8),'_')?:'user';$username='oauth_'.$base.'_'.bin2hex(random_bytes(3));
   while(row('SELECT id FROM users WHERE username=? LIMIT 1',[$username]))$username='oauth_'.$base.'_'.bin2hex(random_bytes(3));
   db()->beginTransaction();
   try{q('INSERT INTO users(username,email,password_hash,role) VALUES(?,?,NULL,?)',[$username,$email,'user']);$userId=(int)db()->lastInsertId();q('INSERT INTO oauth_accounts(user_id,provider,provider_user_id) VALUES(?,?,?)',[$userId,$provider,$providerId]);db()->commit();}
   catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
   $account=row('SELECT * FROM users WHERE id=?',[$userId]);
  }
  session_regenerate_id(true);$_SESSION['user_id']=(int)$account['id'];$_SESSION['csrfToken']=bin2hex(random_bytes(32));go('/app');
 }catch(Throwable $e){error_log('C8B OAuth callback failed: '.$e->getMessage());go('/login?error=oauth_failed');}
}

function render_auth(string $file): never{$html=@file_get_contents(rootdir().'/views/'.$file)?:'';$g=(bool)(getenv('GOOGLE_CLIENT_ID')&&getenv('GOOGLE_CLIENT_SECRET'));$d=(bool)(getenv('DISCORD_CLIENT_ID')&&getenv('DISCORD_CLIENT_SECRET'));if(!$g)$html=preg_replace('~<a class="oauth-button" href="/auth/google" id="google-login">Google</a>~','',$html)??$html;if(!$d)$html=preg_replace('~<a class="oauth-button" href="/auth/discord" id="discord-login">Discord</a>~','',$html)??$html;if(!$g&&!$d)$html=preg_replace('~<div class="divider">[\s\S]*?</div>\s*<div class="oauth-buttons">[\s\S]*?</div>~','',$html)??$html;header('Content-Type: text/html; charset=utf-8');header('Cache-Control: no-store, private');echo $html;exit;}
function page(string $title,string $desc,string $active,string $content): void{$shell=@file_get_contents(rootdir().'/views/public.html')?:'';$u=user_now();$actions=$u?'<button class="button button-secondary button-small" type="button" data-logout>Sign out</button>':'<a class="button button-secondary button-small" href="/login">Sign in</a><a class="button button-primary button-small" href="/register">Join C8B</a>';$replace=['{{PAGE_TITLE}}'=>h($title),'{{META_DESCRIPTION}}'=>h(substr($desc,0,250)),'{{HEADER_ACTIONS}}'=>$actions,'{{CONTENT}}'=>$content,'{{NAV_HOME}}'=>$active==='home'?'aria-current="page"':'','{{NAV_PROJECTS}}'=>in_array($active,['projects','detail'],true)?'aria-current="page"':'','{{NAV_ABOUT}}'=>$active==='about'?'aria-current="page"':'','{{NAV_CONTACT}}'=>$active==='contact'?'aria-current="page"':''];echo strtr($shell,$replace);}
function error_page(int $status,string $heading,string $message): never{http_response_code($status);page(($status===404?'404':($status===403?'403':'500')).' — '.$heading,$message,'','<section class="error-wrap"><div><span class="error-code">'.$status.' / C8B</span><h1>'.h($heading).'</h1><p>'.h($message).'</p><a class="button button-primary" href="/">Back to home</a> <a class="button button-secondary" href="/projects">Explore projects</a></div></section>');exit;}
function card(array $p): string{$icon=murl($p['icon_path']??'');$cat=$p['category_name']?:'Uncategorized';$slug=rawurlencode($p['slug']);$img=$icon?'<img src="'.$icon.'" alt="" loading="lazy">':'<span class="cover-monogram">'.h(strtoupper(substr($p['title'],0,2))).'</span>';$desc=h($p['description']?:'A C8B project. Explore the details and available files.');$download=(int)$p['file_count']>0?'<a class="button button-secondary button-small" href="/projects/'.$slug.'#downloads">Download</a>':'';return '<article class="project-card" data-project-card data-name="'.h(strtolower($p['title'].' '.$p['description'])).'" data-category="'.h($p['category_slug']??'').'" data-version="'.h($p['version']).'"><a class="project-cover" href="/projects/'.$slug.'">'.$img.'</a><div class="project-body"><div class="project-meta"><span class="pill pill-accent">'.h($cat).'</span><span class="pill">v'.h($p['version']).'</span>'.((int)$p['featured']?'<span class="pill">Featured</span>':'').'</div><h3><a href="/projects/'.$slug.'">'.h($p['title']).'</a></h3><p>'.$desc.'</p><div class="project-card-foot"><span class="download-count">↓ '.number_format((int)$p['download_count']).' downloads</span><div class="project-actions"><a class="text-link" href="/projects/'.$slug.'">View project →</a>'.$download.'</div></div></div></article>';}
function grid(array $ps,string $title='Nothing published just yet',string $desc='New projects will show up here soon.'): string{return $ps?implode('',array_map('card',$ps)):'<div class="empty-state"><strong>'.h($title).'</strong>'.h($desc).'</div>';}
function categories_public(): array{return rows("SELECT c.id,c.name,c.slug,c.description,(SELECT COUNT(*) FROM projects p WHERE p.category_id=c.id AND p.status='published') project_count FROM categories c WHERE EXISTS(SELECT 1 FROM projects p WHERE p.category_id=c.id AND p.status='published') ORDER BY project_count DESC,c.name LIMIT 12");}
function pub_projects(): array{return rows(base_projects()." WHERE p.status='published' ORDER BY p.created_at DESC");}
function stats_html(): string{$p=nrows("SELECT COUNT(*) n FROM projects WHERE status='published'");$d=nrows("SELECT COUNT(*) n FROM downloads d JOIN project_files f ON f.id=d.project_file_id JOIN projects p ON p.id=f.project_id WHERE p.status='published' AND f.status='active'");$u=nrows("SELECT COUNT(*) n FROM users WHERE role='user' AND is_active=1");return '<div class="stats-strip"><div class="container stats-grid"><div class="stat-item"><span class="stat-mark">▦</span><div><strong>'.number_format($p).'</strong><span>Published projects</span></div></div><div class="stat-item"><span class="stat-mark">↓</span><div><strong>'.number_format($d).'</strong><span>Downloads tracked</span></div></div><div class="stat-item"><span class="stat-mark">♙</span><div><strong>'.number_format($u).'</strong><span>Community members</span></div></div></div></div>';}
function home_html(): string{$featured=rows(base_projects()." WHERE p.status='published' AND p.featured=1 ORDER BY p.updated_at DESC LIMIT 3");$latest=array_slice(pub_projects(),0,6);$cats=categories_public();$cc='';$symbols=['◇','▦','⌘','✦'];foreach($cats as $i=>$c)$cc.='<a class="category-card" href="/projects?category='.rawurlencode($c['slug']).'"><span class="category-icon">'.$symbols[$i%4].'</span><span><strong>'.h($c['name']).'</strong><small>'.(int)$c['project_count'].' projects</small></span></a>';if(!$cc)$cc='<div class="empty-state"><strong>Categories are on the way</strong>Projects will be grouped here as the catalogue grows.</div>';
return '<section class="hero"><div class="container hero-grid"><div class="hero-copy"><div class="hero-brand"><img src="/assets/logo.svg" data-primary="/assets/logo.jpeg" alt="C8B logo"><span>C8B · CREATOR COMMUNITY</span></div><span class="eyebrow">A home for what you build</span><h1>Build. Create.<span>Share.</span></h1><p class="hero-lede">A growing home for projects, games, tools, Minecraft builds, Roblox experiences, Discord bots, applications, and the ideas behind them. Discover something useful, find inspiration, and share what you make.</p><div class="hero-actions"><a class="button button-primary" href="/projects">Explore projects <span>→</span></a><a class="button button-secondary" href="https://discord.gg/3rV8GwSfSw" target="_blank" rel="noopener noreferrer">Join Discord ↗</a><a class="button button-secondary" href="https://youtube.com/@cha8abb?si=MW5Gg5SKqKh9wWaR" target="_blank" rel="noopener noreferrer">YouTube ↗</a></div><div class="hero-note"><span class="status-dot"></span>Independent projects. Shared with the community.</div></div><div class="hero-visual"><div class="showcase-card"><div class="showcase-top"><div class="showcase-title"><span class="showcase-mini-logo">C8B</span><span>Creator workspace</span></div><span class="showcase-status">Live catalogue</span></div><div class="showcase-art"><div class="art-grid"></div><div class="art-copy"><small>Build something good</small><strong>Ideas become<br>real projects.</strong><span>Tools · Games · Communities · Code</span></div></div><div class="showcase-list"><div class="showcase-row"><span class="showcase-row-icon">⌘</span><span class="showcase-row-copy"><strong>Tools & applications</strong><small>Utilities made to be useful</small></span><span class="showcase-row-tag">01</span></div><div class="showcase-row"><span class="showcase-row-icon">◇</span><span class="showcase-row-copy"><strong>Games & experiences</strong><small>Minecraft, Roblox, and more</small></span><span class="showcase-row-tag">02</span></div><div class="showcase-row"><span class="showcase-row-icon">✦</span><span class="showcase-row-copy"><strong>Bots & community projects</strong><small>Small ideas, real impact</small></span><span class="showcase-row-tag">03</span></div></div></div></div></div></section>'.stats_html().'<section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">Hand-picked</span><h2>Featured projects</h2><p>Standout projects from the C8B catalogue.</p></div><a class="text-link" href="/projects">View all projects →</a></div><div class="project-grid">'.grid($featured,'Featured projects will appear here','The Owner can feature published projects from the dashboard.').'</div></div></section><section class="section section-after"><div class="container"><div class="section-head"><div><span class="eyebrow">Fresh from the community</span><h2>Latest projects</h2><p>Explore recently published releases and experiments.</p></div><a class="text-link" href="/projects">Browse catalogue →</a></div><div class="project-grid">'.grid($latest,'The catalogue is getting ready','Once the Owner publishes a project, it will appear here.').'</div></div></section><section class="section section-after-small"><div class="container"><div class="section-head"><div><span class="eyebrow">Find your corner</span><h2>Explore categories</h2><p>Jump into a topic and find projects that match your interests.</p></div></div><div class="category-grid">'.$cc.'</div></div></section><section class="section section-after"><div class="container"><div class="cta-panel"><div><span class="eyebrow">Make something worth sharing</span><h2>Your next project starts here.</h2><p>Join the community, discover new ideas, and keep an eye on what creators are publishing next.</p></div><div class="cta-actions"><a class="button button-primary" href="/register">Join C8B</a><a class="button button-secondary" href="https://discord.gg/3rV8GwSfSw" target="_blank" rel="noopener noreferrer">Join Discord ↗</a></div></div></div></section>';}
function projects_html(): string{$ps=pub_projects();$cats=categories_public();$o='';foreach($cats as $c)$o.='<option value="'.h($c['slug']).'"'.(($c['slug']??'')===($_GET['category']??'')?' selected':'').'>'.h($c['name']).'</option>';$vs=array_unique(array_filter(array_map(fn($p)=>trim((string)$p['version']),$ps)));rsort($vs,SORT_NATURAL);$vo='';foreach($vs as $v)$vo.='<option value="'.h($v).'">'.h($v).'</option>';return '<section class="page-hero"><div class="container"><span class="eyebrow">C8B catalogue</span><h1>Projects, made to be shared.</h1><p>Search tools, games, bots, applications, Minecraft builds, Roblox experiences, and more. Sign in to download files hosted by C8B.</p></div></section><section class="section"><div class="container"><div class="catalog-tools"><div class="field"><label for="project-search">Search projects</label><input class="input" id="project-search" type="search" placeholder="Search by name or description…" autocomplete="off"></div><div class="field"><label for="category-filter">Category</label><select class="select" id="category-filter"><option value="">All categories</option>'.$o.'</select></div><div class="field"><label for="version-filter">Version</label><select class="select" id="version-filter"><option value="">All versions</option>'.$vo.'</select></div></div><p class="filter-result" id="filter-result" aria-live="polite">'.count($ps).' published projects</p><div class="project-grid" id="catalog-grid">'.grid($ps,'No projects published yet','Check back soon — new releases will appear here.').'</div><div class="empty-state" id="filtered-empty" hidden><strong>No projects match those filters</strong>Try a different name, category, or version.</div></div></section>';}
function detail_html(array $p): string{$files=rows("SELECT f.id,f.original_name,f.version,f.size_bytes,f.created_at,(SELECT COUNT(*) FROM downloads d WHERE d.project_file_id=f.id) download_count FROM project_files f WHERE f.project_id=? AND f.status='active' ORDER BY f.created_at DESC",[(int)$p['id']]);$icon=murl($p['icon_path']);$banner=murl($p['banner_path']);$features=arr($p['features_json']);$shots='';foreach(arr($p['screenshots_json']) as $i=>$s){$src=murl($s);if($src)$shots.='<a href="'.$src.'" target="_blank" rel="noopener noreferrer"><img src="'.$src.'" alt="'.h($p['title']).' screenshot '.($i+1).'" loading="lazy"></a>';}$fl=$features?'<ul class="feature-list">'.implode('',array_map(fn($f)=>'<li>'.h($f).'</li>',$features)).'</ul>':'<p>No features have been listed yet.</p>';$links='';foreach(arr($p['external_links_json']) as $l)if(is_array($l)&&!empty($l['label'])&&!empty($l['url'])&&preg_match('~^https?://~i',$l['url']))$links.='<a href="'.h($l['url']).'" target="_blank" rel="noopener noreferrer"><span>'.h($l['label']).'</span><span>↗</span></a>';$items='';$signed=(bool)user_now();foreach($files as $f)$items.='<div class="file-item"><span class="file-icon">↓</span><div class="file-info"><strong>'.h($f['original_name']).'</strong><small>Version '.h($f['version']?:$p['version']).' · '.number_format((int)$f['size_bytes']/1024).' KB</small></div><span class="file-count">'.(int)$f['download_count'].' downloads</span>'.($signed?'<a class="button button-primary button-small" data-confirm-download href="/api/download/'.(int)$f['id'].'">Download</a>':'<a class="button button-primary button-small" href="/login">Sign in to download</a>').'</div>';if(!$items)$items='<div class="empty-state"><strong>No files are available yet</strong>The Owner has not published a downloadable file for this project.</div>';return '<section class="detail-hero">'.($banner?'<img class="detail-banner" src="'.$banner.'" alt="">':'').'<div class="detail-banner-shade"></div><div class="container detail-head"><div class="detail-icon">'.($icon?'<img src="'.$icon.'" alt="'.h($p['title']).' icon">':h(strtoupper(substr($p['title'],0,2)))).'</div><div class="detail-title"><div class="project-meta"><span class="pill pill-accent">'.h($p['category_name']?:'Uncategorized').'</span><span class="pill">Version '.h($p['version']).'</span>'.((int)$p['featured']?'<span class="pill">Featured</span>':'').'</div><h1>'.h($p['title']).'</h1><p>'.h($p['description']?:'A C8B project.').'</p><div class="detail-actions"><a class="button button-primary" href="#downloads">View downloads ↓</a><a class="button button-secondary" href="/projects">Back to projects</a></div></div></div></section><section class="section"><div class="container detail-layout"><div class="detail-main"><article class="content-panel"><h2>About this project</h2><p>'.h($p['description']?:'No extended description has been provided.').'</p></article><article class="content-panel"><h2>Features</h2>'.$fl.'</article><article class="content-panel"><h2>Requirements</h2><p>'.h($p['requirements']?:'No specific requirements have been listed.').'</p></article><article class="content-panel"><h2>Screenshots</h2>'.($shots?'<div class="screenshots">'.$shots.'</div>':'<p>No screenshots have been added yet.</p>').'</article><article class="content-panel"><h2>Changelog</h2><p>'.h($p['changelog']?:'No changelog has been published.</p>').'</article><article class="content-panel" id="downloads"><h2>Downloads</h2><p class="downloads-intro">Files are hosted on C8B. Sign in is required to download files and keep download statistics accurate.</p><div class="file-list">'.$items.'</div></article></div><aside class="detail-sidebar"><article class="content-panel"><h2>Project details</h2><dl class="meta-list"><div class="meta-row"><dt>Category</dt><dd>'.h($p['category_name']?:'Uncategorized').'</dd></div><div class="meta-row"><dt>Version</dt><dd>'.h($p['version']).'</dd></div><div class="meta-row"><dt>Published</dt><dd>'.h(date('M j, Y',strtotime($p['created_at']))).'</dd></div><div class="meta-row"><dt>Downloads</dt><dd>'.(int)$p['download_count'].'</dd></div><div class="meta-row"><dt>Available files</dt><dd>'.count($files).'</dd></div></dl></article><article class="content-panel"><h2>External links</h2>'.($links?'<div class="external-list">'.$links.'</div>':'<p>No external links have been added.</p>').'</article><article class="content-panel"><h2>Share C8B</h2><p>Found something useful? Join the community and share it with others.</p><a class="button button-secondary button-small" href="https://discord.gg/3rV8GwSfSw">Join Discord ↗</a></article></aside></div></section>';}
function owner_api(string $p,string $m): never{
