 if(preg_match('~^/api/owner/files/([0-9]+)$~',$p,$x)){$id=(int)$x[1];$f=get_file($id);if(!$f)api(['error'=>'File not found.'],404);if($m==='PUT'){$b=body();q('UPDATE project_files SET original_name=?,version=?,status=? WHERE id=?',[txt($b['filename']??$f['original_name'],180),txt($b['version']??$f['version'],40)?:'1.0.0',in_array($b['status']??'', ['active','inactive'],true)?$b['status']:$f['status'],$id]);api(['success'=>true]);}if($m==='DELETE'){$b=body();if(($b['confirmFilename']??'')!==$f['original_name'])api(['error'=>'Type the exact filename to confirm deletion.'],400);remove_file($fr,$f['stored_name']);q('DELETE FROM project_files WHERE id=?',[$id]);api(['success'=>true]);}}
